/**
 * Copy the frozen protocol vectors from the Python test suite into the web app.
 *
 * `ankerproto/tests/vectors.json` is generated by the Python client and acts as
 * the contract between the two implementations: if either drifts, both test
 * suites fail. Keeping a copy here means the web tests run with no Python
 * dependency, and the copy is refreshed explicitly rather than implicitly.
 *
 * Usage:
 *   node scripts/sync-vectors.mjs           # copy
 *   node scripts/sync-vectors.mjs --check   # fail if out of date (used in CI)
 */

import { copyFileSync, existsSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const webRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
const source = resolve(webRoot, "..", "tests", "vectors.json");
const dest = join(webRoot, "tests", "vectors.json");

if (!existsSync(source)) {
  console.error(
    `Vectors not found at ${source}.\n` +
      "Generate them from the Python client first:\n" +
      "  cd .. && python tests/generate_vectors.py",
  );
  process.exit(2);
}

const check = process.argv.includes("--check");
const src = readFileSync(source, "utf8");

if (check) {
  if (!existsSync(dest)) {
    console.error("tests/vectors.json is missing; run `npm run sync-vectors`.");
    process.exit(1);
  }
  if (readFileSync(dest, "utf8") !== src) {
    console.error(
      "tests/vectors.json is out of date with the Python vectors.\n" +
        "Run `npm run sync-vectors` and commit the result.",
    );
    process.exit(1);
  }
  console.log("vectors are up to date");
  process.exit(0);
}

copyFileSync(source, dest);
const parsed = JSON.parse(src);
console.log(
  `synced vectors: ${parsed.frames.length} frames, ${parsed.crypto.length} crypto, ` +
    `${Object.keys(parsed.opcodes).length} opcodes, ` +
    `${parsed.real_payload.tags.length} captured tags`,
);
